MODULE_SOURCE = '\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom types import MappingProxyType\nfrom typing import Any, Mapping, Tuple\n\nfrom .universal_market_discovery_foundation import (\n    UMD_SUBSYSTEM_ID,\n    ImmutableLineage,\n    deterministic_sha256,\n)\nfrom .umd_047_venue_discovery_request_contract import (\n    ALLOWED_DISCOVERY_SCOPES,\n    CertifiedVenueDiscoveryRequestContract,\n)\n\nUMD_048_BUILD_ID = "UMD-048"\nUMD_048_BUILD_NAME = "Certified Venue Discovery Request Admission Gate"\nUMD_048_REVISION = (\n    "UMD_048_CERTIFIED_VENUE_DISCOVERY_REQUEST_ADMISSION_GATE_V1"\n)\nUMD_048_SCHEMA_VERSION = "1.0.0"\n\nPROHIBITED_CAPABILITIES = (\n    "network_invocation",\n    "authentication_execution",\n    "credential_storage",\n    "automatic_discovery",\n    "automatic_pagination",\n    "automatic_admission_commit",\n    "ledger_append",\n    "request_persistence",\n    "registry_mutation",\n    "publication",\n    "order_submission",\n    "trade_execution",\n)\n\n\ndef _text(value: str, field_name: str) -> str:\n    if not isinstance(value, str):\n        raise TypeError(f"{field_name} must be a string")\n    normalized = " ".join(value.strip().split())\n    if not normalized:\n        raise ValueError(f"{field_name} must not be empty")\n    return normalized\n\n\ndef _sha256(value: str, field_name: str) -> str:\n    normalized = _text(value, field_name).lower()\n    if len(normalized) != 64:\n        raise ValueError(\n            f"{field_name} must contain 64 hexadecimal characters"\n        )\n    if any(character not in "0123456789abcdef" for character in normalized):\n        raise ValueError(\n            f"{field_name} must be lowercase SHA-256 hexadecimal"\n        )\n    return normalized\n\n\ndef _normalized_text_tuple(\n    values: Tuple[str, ...],\n    field_name: str,\n) -> Tuple[str, ...]:\n    if not isinstance(values, tuple):\n        values = tuple(values)\n    return tuple(sorted({_text(value, field_name) for value in values}))\n\n\ndef _normalized_hash_tuple(\n    values: Tuple[str, ...],\n    field_name: str,\n) -> Tuple[str, ...]:\n    if not isinstance(values, tuple):\n        values = tuple(values)\n    return tuple(sorted({_sha256(value, field_name) for value in values}))\n\n\n@dataclass(frozen=True, slots=True)\nclass CertifiedVenueDiscoveryRequestAdmissionDecision:\n    request_id: str\n    request_hash: str\n    source_id: str\n    source_contract_hash: str\n    source_registry_hash: str\n    admitted: bool\n    checks: Mapping[str, bool]\n    rejection_reasons: Tuple[str, ...]\n    lineage: ImmutableLineage\n\n    def __post_init__(self) -> None:\n        object.__setattr__(self, "request_id", _text(self.request_id, "request_id"))\n        object.__setattr__(self, "request_hash", _sha256(self.request_hash, "request_hash"))\n        object.__setattr__(self, "source_id", _text(self.source_id, "source_id"))\n        object.__setattr__(\n            self,\n            "source_contract_hash",\n            _sha256(self.source_contract_hash, "source_contract_hash"),\n        )\n        object.__setattr__(\n            self,\n            "source_registry_hash",\n            _sha256(self.source_registry_hash, "source_registry_hash"),\n        )\n\n        normalized_checks = MappingProxyType(\n            dict(\n                sorted(\n                    (_text(str(name), "check name"), bool(passed))\n                    for name, passed in self.checks.items()\n                )\n            )\n        )\n        object.__setattr__(self, "checks", normalized_checks)\n\n        failed_checks = tuple(\n            name for name, passed in normalized_checks.items() if not passed\n        )\n        reasons = tuple(\n            sorted(\n                {\n                    _text(reason, "rejection reason")\n                    for reason in self.rejection_reasons\n                }\n            )\n        )\n        object.__setattr__(self, "rejection_reasons", reasons)\n\n        if self.admitted:\n            if failed_checks or reasons:\n                raise ValueError(\n                    "admitted decisions cannot contain failed checks"\n                )\n        else:\n            if not failed_checks:\n                raise ValueError(\n                    "rejected decisions require at least one failed check"\n                )\n            if reasons != tuple(sorted(failed_checks)):\n                raise ValueError(\n                    "rejection reasons must exactly match failed checks"\n                )\n\n        if self.lineage.subsystem_id != UMD_SUBSYSTEM_ID:\n            raise ValueError("decision lineage must belong to UMD")\n        if self.lineage.build_id != UMD_048_BUILD_ID:\n            raise ValueError("decision lineage must use build_id UMD-048")\n\n        required_parent_hashes = {\n            self.request_hash,\n            self.source_contract_hash,\n            self.source_registry_hash,\n        }\n        if not required_parent_hashes.issubset(\n            set(self.lineage.parent_hashes)\n        ):\n            raise ValueError(\n                "decision lineage must include request, source-contract, "\n                "and source-registry hashes"\n            )\n\n    @property\n    def decision_id(self) -> str:\n        return "umd:venue-discovery-request-admission:" + deterministic_sha256(\n            {\n                "request_id": self.request_id,\n                "request_hash": self.request_hash,\n                "source_id": self.source_id,\n                "admitted": self.admitted,\n                "checks": self.checks,\n            }\n        )\n\n    def to_canonical_dict(self) -> Mapping[str, Any]:\n        return {\n            "decision_id": self.decision_id,\n            "request_id": self.request_id,\n            "request_hash": self.request_hash,\n            "source_id": self.source_id,\n            "source_contract_hash": self.source_contract_hash,\n            "source_registry_hash": self.source_registry_hash,\n            "admitted": self.admitted,\n            "checks": self.checks,\n            "rejection_reasons": self.rejection_reasons,\n            "lineage": self.lineage,\n        }\n\n    @property\n    def record_hash(self) -> str:\n        return deterministic_sha256(self.to_canonical_dict())\n\n\ndef evaluate_venue_discovery_request_admission(\n    request: CertifiedVenueDiscoveryRequestContract,\n    *,\n    known_request_ids: Tuple[str, ...] = (),\n    known_request_hashes: Tuple[str, ...] = (),\n    lineage: ImmutableLineage,\n) -> CertifiedVenueDiscoveryRequestAdmissionDecision:\n    if not isinstance(request, CertifiedVenueDiscoveryRequestContract):\n        raise TypeError("request must be a certified UMD-047 request")\n\n    normalized_request_ids = _normalized_text_tuple(\n        known_request_ids,\n        "known_request_id",\n    )\n    normalized_request_hashes = _normalized_hash_tuple(\n        known_request_hashes,\n        "known_request_hash",\n    )\n\n    checks = {\n        "request_hash_deterministic": (\n            request.request_hash\n            == deterministic_sha256(request.to_canonical_dict())\n        ),\n        "request_lineage_bound": (\n            {\n                request.source_contract_hash,\n                request.source_registry_hash,\n            }.issubset(set(request.lineage.parent_hashes))\n        ),\n        "request_read_only": request.read_only is True,\n        "discovery_scope_certified": (\n            request.discovery_scope in ALLOWED_DISCOVERY_SCOPES\n        ),\n        "requested_statuses_present": bool(request.requested_statuses),\n        "requested_market_families_present": bool(\n            request.requested_market_families\n        ),\n        "time_window_order_valid": (\n            request.window_start is None\n            or request.window_end is None\n            or request.window_end >= request.window_start\n        ),\n        "page_size_valid": (\n            request.page_size is None\n            or 1 <= request.page_size <= 10000\n        ),\n        "request_id_not_previously_seen": (\n            request.request_id not in normalized_request_ids\n        ),\n        "request_hash_not_previously_seen": (\n            request.request_hash not in normalized_request_hashes\n        ),\n        "network_not_invoked": True,\n        "persistence_not_invoked": True,\n    }\n\n    failed = tuple(name for name, passed in checks.items() if not passed)\n\n    return CertifiedVenueDiscoveryRequestAdmissionDecision(\n        request_id=request.request_id,\n        request_hash=request.request_hash,\n        source_id=request.source_id,\n        source_contract_hash=request.source_contract_hash,\n        source_registry_hash=request.source_registry_hash,\n        admitted=not failed,\n        checks=checks,\n        rejection_reasons=failed,\n        lineage=lineage,\n    )\n\n\n@dataclass(frozen=True, slots=True)\nclass UMD048CertificationManifest:\n    subsystem_id: str\n    build_id: str\n    revision: str\n    schema_version: str\n    upstream_builds: Tuple[str, ...]\n    gate_mode: str\n    prohibited_capabilities: Tuple[str, ...]\n    network_enabled: bool\n    persistence_enabled: bool\n    mutation_enabled: bool\n    publication_enabled: bool\n    execution_enabled: bool\n\n    def to_canonical_dict(self) -> Mapping[str, Any]:\n        return {\n            "subsystem_id": self.subsystem_id,\n            "build_id": self.build_id,\n            "revision": self.revision,\n            "schema_version": self.schema_version,\n            "upstream_builds": self.upstream_builds,\n            "gate_mode": self.gate_mode,\n            "prohibited_capabilities": self.prohibited_capabilities,\n            "network_enabled": self.network_enabled,\n            "persistence_enabled": self.persistence_enabled,\n            "mutation_enabled": self.mutation_enabled,\n            "publication_enabled": self.publication_enabled,\n            "execution_enabled": self.execution_enabled,\n        }\n\n    @property\n    def manifest_hash(self) -> str:\n        return deterministic_sha256(self.to_canonical_dict())\n\n\ndef build_umd_048_certification_manifest() -> UMD048CertificationManifest:\n    return UMD048CertificationManifest(\n        subsystem_id="UMD",\n        build_id=UMD_048_BUILD_ID,\n        revision=UMD_048_REVISION,\n        schema_version=UMD_048_SCHEMA_VERSION,\n        upstream_builds=tuple(\n            f"UMD-{number:03d}" for number in range(1, 48)\n        ),\n        gate_mode="deterministic_read_only_admission",\n        prohibited_capabilities=PROHIBITED_CAPABILITIES,\n        network_enabled=False,\n        persistence_enabled=False,\n        mutation_enabled=False,\n        publication_enabled=False,\n        execution_enabled=False,\n    )\n\n\ndef certify_umd_048_foundation() -> Mapping[str, Any]:\n    manifest = build_umd_048_certification_manifest()\n    checks = {\n        "subsystem_identity": manifest.subsystem_id == "UMD",\n        "build_identity": manifest.build_id == "UMD-048",\n        "upstreams_frozen": (\n            manifest.upstream_builds\n            == tuple(\n                f"UMD-{number:03d}" for number in range(1, 48)\n            )\n        ),\n        "gate_mode": (\n            manifest.gate_mode == "deterministic_read_only_admission"\n        ),\n        "network_disabled": manifest.network_enabled is False,\n        "persistence_disabled": manifest.persistence_enabled is False,\n        "mutation_disabled": manifest.mutation_enabled is False,\n        "publication_disabled": manifest.publication_enabled is False,\n        "execution_disabled": manifest.execution_enabled is False,\n        "deterministic_manifest": (\n            manifest.manifest_hash\n            == deterministic_sha256(manifest.to_canonical_dict())\n        ),\n    }\n    failed = tuple(name for name, passed in checks.items() if not passed)\n    return MappingProxyType(\n        {\n            "certified": not failed,\n            "build_id": manifest.build_id,\n            "revision": manifest.revision,\n            "manifest_hash": manifest.manifest_hash,\n            "checks": MappingProxyType(checks),\n            "failed_checks": failed,\n        }\n    )\n\n\ndef verify_umd_048_venue_discovery_request_admission_gate() -> bool:\n    result = certify_umd_048_foundation()\n    if not result["certified"]:\n        raise RuntimeError(\n            "UMD-048 foundation certification failed: "\n            + ", ".join(result["failed_checks"])\n        )\n    return True\n'
TEST_SOURCE = '\nfrom __future__ import annotations\n\nimport unittest\nfrom dataclasses import FrozenInstanceError\nfrom datetime import datetime, timezone\n\nfrom qseries_v2.universal_market_discovery.universal_market_discovery_foundation import (\n    ImmutableLineage,\n)\nfrom qseries_v2.universal_market_discovery.umd_045_venue_discovery_source_contract import (\n    UMD_045_REVISION,\n    CertifiedVenueDiscoverySourceContract,\n)\nfrom qseries_v2.universal_market_discovery.umd_046_venue_discovery_source_registry import (\n    UMD_046_REVISION,\n    CertifiedVenueDiscoverySourceRegistry,\n)\nfrom qseries_v2.universal_market_discovery.umd_047_venue_discovery_request_contract import (\n    UMD_047_REVISION,\n    build_venue_discovery_request_contract,\n)\nfrom qseries_v2.universal_market_discovery.umd_048_venue_discovery_request_admission_gate import (\n    UMD_048_REVISION,\n    CertifiedVenueDiscoveryRequestAdmissionDecision,\n    build_umd_048_certification_manifest,\n    certify_umd_048_foundation,\n    evaluate_venue_discovery_request_admission,\n)\n\nFIXED = datetime(2026, 8, 6, 20, 20, 0, tzinfo=timezone.utc)\n\n\ndef source():\n    lineage = ImmutableLineage(\n        subsystem_id="UMD",\n        build_id="UMD-045",\n        revision=UMD_045_REVISION,\n        schema_version="1.0.0",\n        parent_hashes=(),\n        source_refs=("fixture://umd-048/source",),\n        created_at=FIXED,\n    )\n    return CertifiedVenueDiscoverySourceContract(\n        canonical_venue_id="KALSHI",\n        adapter_key="KALSHI_MARKET_CATALOG",\n        display_name="Kalshi Market Catalog",\n        discovery_method="REST_CATALOG",\n        authentication_mode="API_KEY",\n        pagination_mode="CURSOR",\n        supported_market_families=("BINARY_MARKET", "EVENT_CONTRACT"),\n        supported_statuses=("ACTIVE", "CLOSED", "SETTLED"),\n        source_schema_version="v1",\n        supports_incremental_discovery=True,\n        supports_historical_markets=True,\n        supports_settlement_status=True,\n        supports_cursor_resume=True,\n        rate_limit_metadata_available=True,\n        read_only=True,\n        metadata={},\n        lineage=lineage,\n    )\n\n\ndef registry(item):\n    lineage = ImmutableLineage(\n        subsystem_id="UMD",\n        build_id="UMD-046",\n        revision=UMD_046_REVISION,\n        schema_version="1.0.0",\n        parent_hashes=(item.contract_hash,),\n        source_refs=("fixture://umd-048/registry",),\n        created_at=FIXED,\n    )\n    return CertifiedVenueDiscoverySourceRegistry(\n        sources=(item,),\n        registry_metadata={},\n        lineage=lineage,\n    )\n\n\ndef request():\n    source_item = source()\n    registry_item = registry(source_item)\n    lineage = ImmutableLineage(\n        subsystem_id="UMD",\n        build_id="UMD-047",\n        revision=UMD_047_REVISION,\n        schema_version="1.0.0",\n        parent_hashes=(\n            source_item.contract_hash,\n            registry_item.registry_hash,\n        ),\n        source_refs=("fixture://umd-048/request",),\n        created_at=FIXED,\n    )\n    return build_venue_discovery_request_contract(\n        registry_item,\n        source_item,\n        discovery_scope="ACTIVE_AND_HISTORICAL",\n        requested_statuses=("ACTIVE", "SETTLED"),\n        requested_market_families=("BINARY_MARKET",),\n        requested_at=FIXED,\n        request_schema_version="v1",\n        lineage=lineage,\n        pagination_cursor="cursor-1",\n        page_size=500,\n        metadata={"read_only": True},\n    )\n\n\ndef gate_lineage(item):\n    return ImmutableLineage(\n        subsystem_id="UMD",\n        build_id="UMD-048",\n        revision=UMD_048_REVISION,\n        schema_version="1.0.0",\n        parent_hashes=(\n            item.request_hash,\n            item.source_contract_hash,\n            item.source_registry_hash,\n        ),\n        source_refs=("fixture://umd-048/gate",),\n        created_at=FIXED,\n    )\n\n\nclass TestUMD048(unittest.TestCase):\n    def test_foundation(self):\n        result = certify_umd_048_foundation()\n        self.assertTrue(result["certified"])\n        self.assertEqual(result["build_id"], "UMD-048")\n\n    def test_valid_request_admitted(self):\n        item = request()\n        decision = evaluate_venue_discovery_request_admission(\n            item,\n            lineage=gate_lineage(item),\n        )\n        self.assertTrue(decision.admitted)\n        self.assertEqual(decision.rejection_reasons, ())\n        self.assertTrue(all(decision.checks.values()))\n\n    def test_deterministic(self):\n        item = request()\n        lineage = gate_lineage(item)\n        first = evaluate_venue_discovery_request_admission(\n            item,\n            lineage=lineage,\n        )\n        second = evaluate_venue_discovery_request_admission(\n            item,\n            lineage=lineage,\n        )\n        self.assertEqual(first.decision_id, second.decision_id)\n        self.assertEqual(first.record_hash, second.record_hash)\n\n    def test_duplicate_request_id_rejected(self):\n        item = request()\n        decision = evaluate_venue_discovery_request_admission(\n            item,\n            known_request_ids=(item.request_id,),\n            lineage=gate_lineage(item),\n        )\n        self.assertFalse(decision.admitted)\n        self.assertIn(\n            "request_id_not_previously_seen",\n            decision.rejection_reasons,\n        )\n\n    def test_duplicate_request_hash_rejected(self):\n        item = request()\n        decision = evaluate_venue_discovery_request_admission(\n            item,\n            known_request_hashes=(item.request_hash,),\n            lineage=gate_lineage(item),\n        )\n        self.assertFalse(decision.admitted)\n        self.assertIn(\n            "request_hash_not_previously_seen",\n            decision.rejection_reasons,\n        )\n\n    def test_lineage_requires_all_hashes(self):\n        item = request()\n        bad = ImmutableLineage(\n            subsystem_id="UMD",\n            build_id="UMD-048",\n            revision=UMD_048_REVISION,\n            schema_version="1.0.0",\n            parent_hashes=(item.request_hash,),\n            source_refs=("fixture://umd-048/bad",),\n            created_at=FIXED,\n        )\n        with self.assertRaises(ValueError):\n            evaluate_venue_discovery_request_admission(\n                item,\n                lineage=bad,\n            )\n\n    def test_decision_consistency(self):\n        item = request()\n        with self.assertRaises(ValueError):\n            CertifiedVenueDiscoveryRequestAdmissionDecision(\n                request_id=item.request_id,\n                request_hash=item.request_hash,\n                source_id=item.source_id,\n                source_contract_hash=item.source_contract_hash,\n                source_registry_hash=item.source_registry_hash,\n                admitted=True,\n                checks={"bad": False},\n                rejection_reasons=("bad",),\n                lineage=gate_lineage(item),\n            )\n\n    def test_immutable(self):\n        item = request()\n        decision = evaluate_venue_discovery_request_admission(\n            item,\n            lineage=gate_lineage(item),\n        )\n        with self.assertRaises((FrozenInstanceError, AttributeError)):\n            decision.admitted = False\n        with self.assertRaises(TypeError):\n            decision.checks["changed"] = False\n\n    def test_side_effects(self):\n        manifest = build_umd_048_certification_manifest()\n        self.assertFalse(manifest.network_enabled)\n        self.assertFalse(manifest.persistence_enabled)\n        self.assertFalse(manifest.mutation_enabled)\n        self.assertFalse(manifest.publication_enabled)\n        self.assertFalse(manifest.execution_enabled)\n\n\nif __name__ == "__main__":\n    print("=" * 72)\n    print(" UMD-048 CERTIFICATION TEST")\n    print(" CERTIFIED VENUE DISCOVERY REQUEST ADMISSION GATE")\n    print("=" * 72)\n    result = unittest.TextTestRunner(verbosity=2).run(\n        unittest.defaultTestLoader.loadTestsFromTestCase(TestUMD048)\n    )\n    if not result.wasSuccessful():\n        raise SystemExit(1)\n\n    manifest = build_umd_048_certification_manifest()\n    print()\n    print(f"[PASS] Build: {manifest.build_id}")\n    print(f"[PASS] Revision: {manifest.revision}")\n    print(f"[PASS] Manifest hash: {manifest.manifest_hash}")\n    print("[PASS] UMD-001 through UMD-047 consumed read-only")\n    print("[PASS] Exact UMD-047 request-contract class consumed")\n    print("[PASS] Deterministic admission decision certified")\n    print("[PASS] Duplicate request ID and hash replay rejected")\n    print("[PASS] Immutable decision lineage certified")\n    print("[PASS] Network, persistence, publication, and execution disabled")\n    print("[DONE] UMD-048 CERTIFIED VENUE DISCOVERY REQUEST ADMISSION GATE CERTIFIED")\n'
