def normalize(source: str) -> str:
    return textwrap.dedent(source).lstrip()

def write_direct(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(normalize(source), encoding="utf-8", newline="\n")

def bounds(source: str) -> tuple[int, int]:
    marker="__all__ = ["; start=source.find(marker)
    if start == -1: raise RuntimeError("UMD package __all__ list is missing")
    opening=source.find("[",start); cursor=opening; depth=0; in_string=False; quote=""; escaped=False
    while cursor < len(source):
        ch=source[cursor]
        if in_string:
            if escaped: escaped=False
            elif ch=="\\": escaped=True
            elif ch==quote: in_string=False
        else:
            if ch in ("'",'"'): in_string=True; quote=ch
            elif ch=="[": depth+=1
            elif ch=="]":
                depth-=1
                if depth==0: return opening,cursor
        cursor+=1
    raise RuntimeError("UMD package __all__ closing bracket is missing")

def update_init() -> None:
    source=INIT.read_text(encoding="utf-8")
    marker="from .umd_048_venue_discovery_request_admission_gate import ("
    if marker not in source: source=source.rstrip()+"\n\n"+normalize(INIT_IMPORT)
    opening,closing=bounds(source); block=source[opening+1:closing]
    missing=[name for name in EXPORTED_NAMES if f'"{name}"' not in block and f"'{name}'" not in block]
    if missing: source=source[:closing]+"".join(f'    "{name}",\n' for name in missing)+source[closing:]
    compile(source,str(INIT),"exec"); write_direct(INIT,source)

def verify_upstream() -> None:
    sys.path.insert(0,str(ROOT))
    try:
        for module_name,verifier_name in UPSTREAM_MODULES:
            module=importlib.import_module("qseries_v2.universal_market_discovery."+module_name)
            verifier=getattr(module,verifier_name,None)
            if verifier is None: raise RuntimeError(f"Certified upstream verifier missing: {module_name}.{verifier_name}")
            if verifier() is not True: raise RuntimeError(f"Certified upstream verification failed: {module_name}")
    finally:
        if str(ROOT) in sys.path: sys.path.remove(str(ROOT))

